"""A WebGL-free 2D viewer of attributed game map tiles and actual POI coordinates."""
from pathlib import Path
from html import escape as e
import json
MAPS=json.loads((Path(__file__).parent/'data/maps.json').read_text())
def render(lang,base):
 t=lambda a,b:b if lang=='ko' else a
 options=''.join(f'<option value="{name}" data-faction="{d["faction"]}">{d["ko"] if lang=="ko" else name}</option>' for name,d in MAPS.items())
 return f'''<section class="world-map" data-world-map><div class="map-toolbar"><div class="faction-switch"><button data-faction="elyos" aria-pressed="true">{t('Elyos','천족')}</button><button data-faction="asmodian" aria-pressed="false">{t('Asmodian','마족')}</button></div><label>{t('My current region','내가 있는 지역')}<select data-world-zone>{options}</select></label><p class="map-route" data-map-route></p></div><div class="map-filterbar"><button data-map-type="quest_episode" aria-pressed="false">◆ {t('Story NPCs','메인 퀘스트')}</button><button data-map-type="kibelisk" aria-pressed="true">⌖ {t('Travel points','이동 거점')}</button><button data-map-type="sealed_dungeon" aria-pressed="false">◇ {t('Skill-point dungeons','성장 재료 던전')}</button><label><input type="checkbox" data-map-hide-done> {t('Hide completed','완료 숨기기')}</label></div><p class="map-purpose" data-map-purpose></p><div class="map-workspace"><div class="map-visual"><div class="map-viewport" data-map-viewport tabindex="0" aria-label="{t('Map. Drag to pan; arrow keys also move it.','지도. 드래그 또는 방향키로 이동할 수 있어요.')}" role="region"><div class="map-world" data-map-world><div class="map-tiles" data-map-tiles></div><div data-map-pins></div></div></div><div class="world-map-controls"><button data-world-zoom="out" aria-label="{t('Zoom out','지도 축소')}">−</button><button data-world-zoom="in" aria-label="{t('Zoom in','지도 확대')}">＋</button><button data-world-fit>{t('Show all points','전체 위치 보기')}</button><span data-world-zoom-label></span></div><p class="tiny map-readout" data-map-load-status>{t('Click a marker or choose a place from the list. Drag the map to explore.','마커 또는 옆 목록에서 장소를 골라보세요. 지도를 드래그해서 이동해요.')}</p></div><aside class="map-sidebar"><label class="map-search"><span>{t('Find a place','장소 찾기')}</span><input type="search" data-map-search placeholder="{t('Search the game’s English name…','게임의 영문 지명으로 검색…')}"></label><p data-map-count role="status" class="tiny"></p><div class="map-place-list" data-map-list></div><p data-map-empty hidden></p></aside></div><article class="map-selection" data-map-selection hidden><div class="map-selected-heading"><div><span class="section-kicker" data-map-selected-type></span><h2 data-map-selected-name></h2><p data-map-selected-desc></p></div><button class="btn" data-map-complete aria-pressed="false">{t('Mark complete','완료 표시')}</button></div><div class="map-instructions"><div><small>{t('DO THIS IN GAME','게임에서 할 일')}</small><p data-map-action></p></div><div><small>{t('WHY THIS MATTERS','왜 중요한가요?')}</small><p data-map-reward></p></div><div><small>{t('NEARBY TRAVEL POINT','가까운 이동 거점')}</small><button class="text-link" data-map-nearest></button><p class="tiny muted">{t('Closest in straight-line distance; terrain and unlocks still matter.','좌표상 직선거리 기준이에요. 지형·해금 여부는 게임에서 확인하세요.')}</p></div></div><div class="map-detail-actions"><span data-map-coordinate></span><button class="text-link" data-map-copy>{t('Copy location link','이 위치 링크 복사')}</button><span data-map-copy-status role="status"></span><a data-map-source target="_blank" rel="noopener noreferrer">TH.GL {t('original marker','원본 위치')} ↗</a></div></article><p class="map-credit"><a data-world-credit href="https://aion2.th.gl/maps/Poeta" target="_blank" rel="noopener noreferrer">AION 2 maps by The Hidden Gaming Lair ↗</a><span>© NC Corporation · {t('Actual map tiles and POI coordinates; guidance and completion tracking by CODEX.','실제 지도 타일·위치 좌표 사용. 할 일 설명·완료 관리는 CODEX 제공.')}</span></p><details class="evidence"><summary>{t('Map coverage & saved progress','지도 범위와 완료 표시')}</summary><p>{t('Four starting regions, 384 story / travel / sealed-dungeon points. This is a location reference, not a live character tracker. Local checks stay in this browser. Source snapshot: 2026-10-07; prerequisites can hide a quest in game.','시작 지역 4개에 메인 퀘스트·이동 거점·봉인 던전 384곳을 담았어요. 위치 참고 지도이며 내 캐릭터를 실시간 추적하지 않아요. 완료 표시는 이 브라우저에 저장돼요. 2026-10-07 자료 기준이며 선행 조건에 따라 게임에서 퀘스트가 보이지 않을 수 있어요.')}</p><button class="text-link" data-map-reset>{t('Reset map checkmarks','지도 완료 표시 초기화')}</button></details><script type="application/json" id="world-map-data">{json.dumps(MAPS,ensure_ascii=False).replace('<',chr(92)+'u003c')}</script></section>'''
